#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct N {
    int key;
    struct N *left, *right;
} N;
int main(void)
{
    N m = {20, NULL, NULL}, x = {10, NULL, &m}, y = {30, &x, NULL};
    N *root = &y, *next = root->left, *middle = next->right;
    root->left = middle;
    next->right = root;
    root = next;
    printf("%d %d\n", root->key, root->right->left->key);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void)
{
    int a = 0, b = 1;
    for (int h = 2; h <= 4; h++) {
        int c = 1 + a + b;
        a = b;
        b = c;
    }
    printf("%d\n", b);
    return 0;
}
